export type CatalogFieldType = 'text' | 'long-text' | 'number' | 'currency' | 'date' | 'boolean' | 'email' | 'phone' | 'select' | 'relation' | 'file'

export interface CatalogField {
  id: string
  label: string
  type: CatalogFieldType
  required?: boolean
  options?: string[]
  relationEntityId?: string
}

export interface CatalogEntity {
  id: string
  label: string
  pluralLabel: string
  primaryField: string
  fields: CatalogField[]
  view?: 'table' | 'kanban' | 'calendar'
  groupBy?: string
  dateField?: string
}

export interface CatalogMetric {
  id: string
  label: string
  entityId: string
  operation: 'count' | 'sum'
  field?: string
  format?: 'number' | 'currency'
  statusNotEquals?: string
}

export interface CatalogWorkflow {
  id: string
  name: string
  entityId: string
  event: 'created' | 'updated'
  field?: string
  equals?: string
  message: string
}

export interface CapabilityDefinition {
  id: string
  label: string
  module: ModuleId
  description: string
  signals: string[]
  dependencies: string[]
  entities: CatalogEntity[]
  pages: Array<{ id: string; label: string; entityId: string; view?: 'table' | 'kanban' | 'calendar' }>
  metrics?: CatalogMetric[]
  workflows?: CatalogWorkflow[]
}


