/** Core packs plus the extended sector coverage, so every NAICS sector resolves to a real base. */
export const industryCapabilityPacks: IndustryCapabilityPack[] = [...corePacks, ...extendedIndustryPacks]

/**
 * The company's own words — and only those.
 *
 * The architecture used to be folded in here too, but BO writes the architecture from the
 * capabilities it already chose, so its labels and descriptions came straight back in as "evidence".
 * The word "approval" inside BO's own description of expense tracking was enough to attach the
 * approvals system to a business that never mentioned approvals, and each round added more. The
 * architecture still has a say through `capabilityIds` and `excludedCapabilityIds`, which is an
 * explicit choice rather than a text match.
 */
function normalizedText(state: BusinessState, _architecture: ArchitectureContext) {
  return [state.companySummary, state.industry, ...state.businessModel, ...state.productsOrServices, ...state.customers, ...state.revenueModel, ...state.team, ...state.operations, ...state.resources, ...state.goals, ...state.knownEntities, ...state.knownWorkflows, ...state.softwareImplications, ...state.facts.map(item => `${item.topic} ${item.value}`)].join(' ').toLowerCase()
}

export function selectIndustryCapabilityPack(text: string) {
  const normalized = text.toLowerCase()
  return industryCapabilityPacks.map(pack => ({ pack, score: pack.signals.reduce((score, signal) => score + (saysSignal(normalized, signal) ? signal.split(' ').length + 1 : 0), 0) })).sort((left, right) => right.score - left.score)[0]
}

function explicitlyExcluded(text: string) {
  const excluded = new Set<string>()
  if (/no (physical|stock|inventory)|do not (sell|store|buy) physical|digital products? only|services? only/.test(text)) ['inventory.stock', 'inventory.warehouses', 'inventory.traceability', 'logistics.shipping', 'manufacturing.bom', 'manufacturing.production', 'quality.inspections', 'procurement.purchasing'].forEach(id => excluded.add(id))
  // "Solo consultant" and "sole trader" are how people describe themselves far more often than "solo
  // founder". The team directory stays whatever they say: twenty-eight capabilities depend on it, so
  // removing it would take tasks, timesheets and the schedule with it. What goes is the staffing
  // administration around it — capacity planning and leave for a company of one.
  if (/no employees|no team|just me|work alone|\bsolo\b|\bsole (trader|operator|practitioner)\b/.test(text)) ['people.time-off', 'people.attendance', 'people.recruiting', 'people.payroll', 'work.resources', 'work.shifts'].forEach(id => excluded.add(id))
  if (/no subscriptions?|one[- ]off only|no recurring/.test(text)) ['subscriptions.billing', 'subscriptions.success'].forEach(id => excluded.add(id))
  if (/no shipping|pickup only|digital delivery/.test(text)) excluded.add('logistics.shipping')
  return excluded
}

export interface CapabilityPlan {
  pack: IndustryCapabilityPack | null
  selected: CapabilityDefinition[]
  excluded: string[]
  reasons: Record<string, string>
  research: BusinessResearch
}

export function planCapabilities(state: BusinessState, architecture: ArchitectureContext): CapabilityPlan {
  const text = normalizedText(state, architecture)
  const research = researchBusiness({ text })
  const selected = new Set<string>()
  const reasons: Record<string, string> = {}
  const explicitExcluded = new Set([...(architecture.excludedCapabilityIds ?? []), ...explicitlyExcluded(text), ...research.exclude.map(item => item.capabilityId)])
  const packMatch = selectIndustryCapabilityPack(`${state.industry} ${state.companySummary}`)
  // When no signal matches, fall back to the industry taxonomy so an unusual business still gets a
  // real operating base rather than the conservative general one.
  const taxonomyPack = packMatch?.score ? null : industryCapabilityPacks.find(item => item.id === research.archetype?.id)
  const pack = packMatch?.score ? packMatch.pack : taxonomyPack ?? null
  for (const id of architecture.capabilityIds ?? []) if (capabilityById.has(id)) { selected.add(id); reasons[id] = 'Selected by BO architecture' }
  for (const decision of research.include) if (capabilityById.has(decision.capabilityId) && !explicitExcluded.has(decision.capabilityId)) { selected.add(decision.capabilityId); reasons[decision.capabilityId] ||= decision.reason }
  if (pack) for (const id of pack.capabilities) if (!explicitExcluded.has(id)) { selected.add(id); reasons[id] ||= `${pack.label} operating base` }
  for (const definition of capabilityCatalog) {
    if (explicitExcluded.has(definition.id) || selected.has(definition.id)) continue
    const signal = definition.signals.find(candidate => saysSignal(text, candidate))
    if (signal) { selected.add(definition.id); reasons[definition.id] = `Business evidence: ${signal}` }
  }
  if (!selected.size) ['crm.contacts', 'finance.invoicing', 'finance.expenses', 'documents.repository'].forEach(id => { selected.add(id); reasons[id] = 'Conservative general-business base' })
  let changed = true
  while (changed) {
    changed = false
    for (const id of [...selected]) for (const dependency of capabilityById.get(id)?.dependencies ?? []) {
      if (!explicitExcluded.has(dependency) && !selected.has(dependency)) { selected.add(dependency); reasons[dependency] = `Required by ${capabilityById.get(id)?.label}`; changed = true }
    }
  }
  for (const id of explicitExcluded) selected.delete(id)
  let pruned = true
  while (pruned) {
    pruned = false
    for (const id of [...selected]) if ((capabilityById.get(id)?.dependencies ?? []).some(dependency => explicitExcluded.has(dependency))) { selected.delete(id); pruned = true }
  }
  return { pack, selected: [...selected].map(id => capabilityById.get(id)).filter(Boolean) as CapabilityDefinition[], excluded: [...explicitExcluded], reasons, research }
}

export function capabilityCatalogPrompt() {
  const grouped = new Map<ModuleId, string[]>()
  for (const item of capabilityCatalog) grouped.set(item.module, [...(grouped.get(item.module) ?? []), `${item.id}=${item.label}`])
  return [...grouped.entries()].map(([module, items]) => `${module}: ${items.join(', ')}`).join('\n')
}
